 "content": "def transform(grid):
    """Copy the only patterned partition into every partition of a grid."""
    h, w = len(grid), len(grid[0])
    # Partition boundaries are the full horizontal/vertical lines of a
    # distinct separator color; determine rectangular cell bounds.
    sep_color = grid[h // 2][0]
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep_color for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep_color for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # Select the one band-pair containing non-background content. The
    # background is the most common non-separator color.
    from collections import Counter
    bg = Counter(v for row in grid for v in row if v != sep_color).most_common(1)[0][0]
    source = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break
    r0, r1, c0, c1 = source
    out = [row[:] for row in grid]
    for br0, br1 in row_bands:
        for bc0, bc1 in col_bands:
            for r in range(br0, br1):
                for c in range(bc0, bc1):
                    out[r][c] = grid[r0 + (r - br0), c0 + (c - bc0)]
    return out
